def table(n): return sorted(i * j for i in range(1, n + 1) for j in range(1, n + 1))
def count(n, x): return sum(min(n, x // i) for i in range(1, n + 1))
result = sum(1 for v in table(4) if v <= 6)

def table(n): return sorted(i * j for i in range(1, n + 1) for j in range(1, n + 1))
def count(n, x): return sum(min(n, x // i) for i in range(1, n + 1))
result = table(4)[6]

def table(n): return sorted(i * j for i in range(1, n + 1) for j in range(1, n + 1))
def count(n, x): return sum(min(n, x // i) for i in range(1, n + 1))
result = next(x for x in range(1, 17) if count(4, x) >= 7)

def table(n): return sorted(i * j for i in range(1, n + 1) for j in range(1, n + 1))
def count(n, x): return sum(min(n, x // i) for i in range(1, n + 1))
assert count(10, 50) == sum(1 for v in table(10) if v <= 50)
result = count(10, 50)

def table(n): return sorted(i * j for i in range(1, n + 1) for j in range(1, n + 1))
def count(n, x): return sum(min(n, x // i) for i in range(1, n + 1))
assert next(x for x in range(1, 10001) if count(100, x) >= 5000) == table(100)[4999]
result = table(100)[4999]
